INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('wadi-al-arbaeen', 'private', NULL, 'oman', NULL, 'Wadi Al Arbaeen', 'وادي العربيين', 'Hidden in the embrace of nature lies a valley ringed by rock walls and adorned with natural pools. Wander the rocky paths, swim in the valley’s waters, and enjoy moments of calm and relaxation far from the noise of everyday life, with the people you love 🌿', 'بين أحضان الطبيعة، يختبئ وادٍ تحيط به الجدران الصخرية، وتزينه البرك المائية الطبيعية. رحلة بين الممرات الصخرية، وسباحة في مياه الوادي، ولحظات من الهدوء والاسترخاء بعيداً عن صخب الحياة، برفقة من تحب 🌿', 'asset:wadi', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 10);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('jabal-akhdar', 'private', NULL, 'oman', NULL, 'Jabal Akhdar', 'الجبل الأخضر', 'Cool mountain air, terraced orchards and wide canyon viewpoints. Ideal for scenic hikes, village walks and a slower pace above the clouds.', 'هواء جبلي منعش ومدرجات زراعية وإطلالات واسعة على الأخاديد. مثالي للمشي في الطبيعة وجولات القرى وإيقاع أهدأ فوق الغيوم.', 'asset:mountains', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 20);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('masirah-island', 'private', NULL, 'oman', NULL, 'Masirah Island', 'جزيرة مصيرة', 'Long empty beaches, clear water and an easy island pace. Plan time for fishing, beach camping and watching the coast from the sea.', 'شواطئ طويلة هادئة ومياه صافية وإيقاع جزيرة مريح. خطط لوقت للصيد والتخييم على الشاطئ ومشاهدة الساحل من البحر.', 'asset:coast', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 30);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('salalah', 'private', NULL, 'oman', NULL, 'Salalah', 'صلالة', 'Green hills, coastal scenery and a very different side of Oman, especially in the khareef season. Explore the coast and valleys at your own pace.', 'تلال خضراء ومناظر ساحلية وجانب مختلف تمامًا من عُمان، خصوصًا في موسم الخريف. استكشف الساحل والأودية بالوتيرة التي تناسبك.', 'asset:camping', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 40);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('jabal-akhdar-trip', 'group', NULL, 'oman', NULL, 'Jabal Akhdar Trip', 'رحلة الجبل الأخضر', 'Two days in the cool mountains: terraced villages, orchards, canyon viewpoints and a guided hike, travelling together with a small group.', 'يومان في الجبال المنعشة: قرى مدرجة وبساتين وإطلالات على الأخاديد ومسار مشي بصحبة مرشد، مع مجموعة صغيرة.', 'asset:mountains', 'Jabal Akhdar, Oman', 'الجبل الأخضر، عُمان', '2 days / 1 night', 'يومان / ليلة واحدة', 'Small group (sample: up to 14 travellers)', 'مجموعة صغيرة (تجريبي: حتى 14 مسافرًا)', NULL, NULL, NULL, 65, 'person', '[{"title":{"en":"Day 1 · Muscat to the mountain","ar":"اليوم 1 · من مسقط إلى الجبل"},"text":{"en":"Morning pick-up in Muscat and a scenic drive up to the plateau. Afternoon village walk through terraced orchards, then sunset at a canyon viewpoint.","ar":"انطلاق صباحي من مسقط وطريق جبلي إلى الهضبة. جولة بعد الظهر بين المدرجات الزراعية ثم غروب الشمس من أحد مواقع الإطلالة."}},{"title":{"en":"Day 1 · Evening","ar":"اليوم 1 · المساء"},"text":{"en":"Group dinner and an overnight stay on the mountain.","ar":"عشاء جماعي ومبيت في الجبل."}},{"title":{"en":"Day 2 · Hike and return","ar":"اليوم 2 · المشي والعودة"},"text":{"en":"Early breakfast and a guided hike with views over the canyon. Lunch, free time, then the drive back to Muscat.","ar":"فطور مبكر ومسار مشي بصحبة مرشد مع إطلالات على الأخدود. غداء ووقت حر ثم العودة إلى مسقط."}}]', '[{"en":"Return transport from Muscat","ar":"النقل ذهابًا وإيابًا من مسقط"},{"en":"One night’s accommodation","ar":"إقامة ليلة واحدة"},{"en":"Meals mentioned in the itinerary","ar":"الوجبات المذكورة في البرنامج"},{"en":"Trip leader / local guide","ar":"قائد الرحلة / مرشد محلي"}]', '[{"en":"Personal expenses and souvenirs","ar":"المصاريف الشخصية والهدايا التذكارية"},{"en":"Travel insurance","ar":"التأمين على السفر"},{"en":"Anything not listed under “What’s included”","ar":"أي شيء غير مذكور ضمن «ما يشمله السعر»"}]', '[]', '[{"en":"SAMPLE TERMS: to be replaced with Earth Adventure’s real terms before publishing.","ar":"شروط تجريبية: تُستبدل بشروط Earth Adventure الفعلية قبل النشر."},{"en":"A seat is confirmed once our team confirms availability and payment arrangements with you.","ar":"يتأكد المقعد بعد أن يؤكد فريقنا التوفر وترتيبات الدفع معك."},{"en":"Cancellation and refund terms are confirmed by our team before you pay.","ar":"يؤكد فريقنا شروط الإلغاء والاسترداد قبل الدفع."},{"en":"The programme may change because of weather, safety or local conditions. Please follow the guide’s instructions.","ar":"قد يتغير البرنامج بسبب الطقس أو السلامة أو الظروف المحلية. يرجى اتباع تعليمات المرشد."}]', 1, 1, 50);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('muscat-trip', 'group', NULL, 'oman', NULL, 'Muscat Trip', 'رحلة مسقط', 'A day exploring Muscat: the coast, the old quarters and the sea, with a small group and a local guide.', 'يوم لاستكشاف مسقط: الساحل والأحياء القديمة والبحر، مع مجموعة صغيرة ومرشد محلي.', 'asset:coast', 'Muscat, Oman', 'مسقط، عُمان', '1 day', 'يوم واحد', 'Small group (sample: up to 14 travellers)', 'مجموعة صغيرة (تجريبي: حتى 14 مسافرًا)', NULL, NULL, NULL, 25, 'person', '[{"title":{"en":"Morning","ar":"الصباح"},"text":{"en":"Meet the group and start along the Muscat coast with the first stops and photo points.","ar":"لقاء المجموعة والانطلاق على طول ساحل مسقط مع أولى المحطات ونقاط التصوير."}},{"title":{"en":"Midday","ar":"الظهيرة"},"text":{"en":"Explore the old quarters and local markets, then lunch together.","ar":"استكشاف الأحياء القديمة والأسواق المحلية ثم غداء جماعي."}},{"title":{"en":"Afternoon","ar":"بعد الظهر"},"text":{"en":"A relaxed time by the sea and a sunset stop before heading back.","ar":"وقت هادئ على البحر ومحطة لمشاهدة الغروب قبل العودة."}}]', '[{"en":"Local transport during the day","ar":"النقل المحلي خلال اليوم"},{"en":"Lunch (sample)","ar":"الغداء (تجريبي)"},{"en":"Trip leader / local guide","ar":"قائد الرحلة / مرشد محلي"}]', '[{"en":"Personal expenses and souvenirs","ar":"المصاريف الشخصية والهدايا التذكارية"},{"en":"Travel insurance","ar":"التأمين على السفر"},{"en":"Anything not listed under “What’s included”","ar":"أي شيء غير مذكور ضمن «ما يشمله السعر»"}]', '[]', '[{"en":"SAMPLE TERMS: to be replaced with Earth Adventure’s real terms before publishing.","ar":"شروط تجريبية: تُستبدل بشروط Earth Adventure الفعلية قبل النشر."},{"en":"A seat is confirmed once our team confirms availability and payment arrangements with you.","ar":"يتأكد المقعد بعد أن يؤكد فريقنا التوفر وترتيبات الدفع معك."},{"en":"Cancellation and refund terms are confirmed by our team before you pay.","ar":"يؤكد فريقنا شروط الإلغاء والاسترداد قبل الدفع."},{"en":"The programme may change because of weather, safety or local conditions. Please follow the guide’s instructions.","ar":"قد يتغير البرنامج بسبب الطقس أو السلامة أو الظروف المحلية. يرجى اتباع تعليمات المرشد."}]', 1, 1, 60);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('masirah-island-trip', 'group', NULL, 'oman', NULL, 'Masirah Island Trip', 'رحلة جزيرة مصيرة', 'Three days on Masirah: long beaches, clear water and island life, travelling together with a small group.', 'ثلاثة أيام في مصيرة: شواطئ طويلة ومياه صافية وحياة الجزيرة، مع مجموعة صغيرة.', 'asset:coast', 'Masirah Island, Oman', 'جزيرة مصيرة، عُمان', '3 days / 2 nights', '3 أيام / ليلتان', 'Small group (sample: up to 12 travellers)', 'مجموعة صغيرة (تجريبي: حتى 12 مسافرًا)', NULL, NULL, NULL, 110, 'person', '[{"title":{"en":"Day 1 · Journey to the island","ar":"اليوم 1 · الرحلة إلى الجزيرة"},"text":{"en":"Travel from Muscat to the departure point, cross to the island and settle in.","ar":"السفر من مسقط إلى نقطة العبور ثم الوصول إلى الجزيرة والاستقرار."}},{"title":{"en":"Day 2 · Island day","ar":"اليوم 2 · يوم الجزيرة"},"text":{"en":"Explore beaches and the coast, with time for the sea and an evening together.","ar":"استكشاف الشواطئ والساحل مع وقت للبحر وأمسية جماعية."}},{"title":{"en":"Day 3 · Return","ar":"اليوم 3 · العودة"},"text":{"en":"Morning on the beach, then the crossing and the journey back to Muscat.","ar":"صباح على الشاطئ ثم العبور والعودة إلى مسقط."}}]', '[{"en":"Transport from Muscat and the island crossing (sample)","ar":"النقل من مسقط وعبور الجزيرة (تجريبي)"},{"en":"Two nights’ accommodation","ar":"إقامة ليلتين"},{"en":"Meals mentioned in the itinerary","ar":"الوجبات المذكورة في البرنامج"},{"en":"Trip leader / local guide","ar":"قائد الرحلة / مرشد محلي"}]', '[{"en":"Personal expenses and souvenirs","ar":"المصاريف الشخصية والهدايا التذكارية"},{"en":"Travel insurance","ar":"التأمين على السفر"},{"en":"Anything not listed under “What’s included”","ar":"أي شيء غير مذكور ضمن «ما يشمله السعر»"}]', '[]', '[{"en":"SAMPLE TERMS: to be replaced with Earth Adventure’s real terms before publishing.","ar":"شروط تجريبية: تُستبدل بشروط Earth Adventure الفعلية قبل النشر."},{"en":"A seat is confirmed once our team confirms availability and payment arrangements with you.","ar":"يتأكد المقعد بعد أن يؤكد فريقنا التوفر وترتيبات الدفع معك."},{"en":"Cancellation and refund terms are confirmed by our team before you pay.","ar":"يؤكد فريقنا شروط الإلغاء والاسترداد قبل الدفع."},{"en":"The programme may change because of weather, safety or local conditions. Please follow the guide’s instructions.","ar":"قد يتغير البرنامج بسبب الطقس أو السلامة أو الظروف المحلية. يرجى اتباع تعليمات المرشد."}]', 1, 1, 70);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('sea-fishing', 'experience', 'sea-fishing', 'oman', NULL, 'Sea Fishing Adventure', 'مغامرة الصيد البحري', 'A fresh perspective, an open horizon, and the possibility of your next great catch. Tell us about the fishing trip you have in mind.', 'آفاق مفتوحة وتجربة مختلفة وفرصة لصيدك القادم. أخبرنا عن رحلة الصيد التي تتطلع إليها.', 'asset:coast', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 80);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('private-boat', 'experience', 'sea-fishing', 'oman', NULL, 'Private Boat Escape', 'رحلة قارب خاصة', 'Make time for the sea with a private boat trip planned around your group. Routes and arrangements are confirmed with our team.', 'استمتع بالبحر في رحلة قارب خاصة تُخطط حسب مجموعتك. تُؤكد المسارات والترتيبات مع فريقنا.', 'asset:coast', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 90);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('camping-escape', 'experience', 'camping-overnight', 'oman', NULL, 'An Escape Under the Stars', 'رحلة تحت النجوم', 'Disconnect from the rush and reconnect with nature. Request an overnight camping escape and discuss the setting and arrangements with us.', 'ابتعد عن صخب الحياة وتواصل مع الطبيعة. اطلب رحلة تخييم ليلية وناقش معنا المكان والترتيبات.', 'asset:camping', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 100);
INSERT INTO trips (slug,kind,category,region,destination,name_en,name_ar,description_en,description_ar,image,location_en,location_ar,duration_en,duration_ar,group_size_en,group_size_ar,max_group,accommodation_en,accommodation_ar,price,price_type,itinerary,inclusions,exclusions,requirements,terms,is_sample,is_active,sort_order) VALUES ('private-camping', 'experience', 'camping-overnight', 'oman', NULL, 'Your Private Camping Getaway', 'رحلة تخييم خاصة', 'An outdoor escape for your own circle. Share your preferences for a private camping experience, from the setting to the length of your stay.', 'رحلة في الطبيعة مع من تحب. شاركنا تفضيلاتك لتجربة تخييم خاصة، من المكان إلى مدة الإقامة.', 'asset:camping', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'contact', '[]', '[]', '[]', '[]', '[]', 0, 1, 110);
